import{_ as s,o as n,c as e,a6 as t}from"./chunks/framework.Buk0QMEt.js";const g=JSON.parse('{"title":"生产环境系统频繁Full GC，如何快速优化？","description":"","frontmatter":{},"headers":[],"relativePath":"content/社区/生产环境系统频繁Full GC，如何快速优化？.md","filePath":"content/社区/生产环境系统频繁Full GC，如何快速优化？.md","lastUpdated":1782273602000}'),p={name:"content/社区/生产环境系统频繁Full GC，如何快速优化？.md"};function l(i,a,o,r,c,d){return n(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="生产环境系统频繁full-gc-如何快速优化" tabindex="-1">生产环境系统频繁Full GC，如何快速优化？ <a class="header-anchor" href="#生产环境系统频繁full-gc-如何快速优化" aria-label="Permalink to &quot;生产环境系统频繁Full GC，如何快速优化？&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>我们在面试时，经常会被面试官问到：线上服务频繁Full GC该如何优化？</p><p>今天这篇文章跟大家一起聊聊这个话题，希望对你会有所帮助。</p><ol><li>什么是Full GC？</li></ol><hr><p>当老年代空间不足时，JVM会触发<code>Stop-The-World</code>的全局回收（Full GC），暂停所有应用线程。</p><p><strong>致命危害</strong>（生产环境实测）：</p><table tabindex="0"><thead><tr><th>暂停时间</th><th>业务影响</th></tr></thead><tbody><tr><td>1秒</td><td>支付超时率上升5%</td></tr><tr><td>3秒</td><td>数据库连接池耗尽</td></tr><tr><td>10秒</td><td>服务被注册中心摘除</td></tr></tbody></table><p><strong>对象的晋升之路流程图：</strong></p><p><img src="https://p3-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/6690375b8ef943979c4f6678f034abf6~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg6IuP5LiJ6K-05oqA5pyv:q75.awebp?rk3s=f64ab15b&amp;x-expires=1782401999&amp;x-signature=3PiHmpQIxEGG5aMOeIG3RUUv9tY%3D" alt=""></p><p><strong>关键代码：年龄计数器</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// HotSpot虚拟机源码片段（objectMonitor.cpp）</span></span>
<span class="line"><span>void ObjectSynchronizer::fast_enter(Handle obj, BasicLock* lock) {</span></span>
<span class="line"><span>if (obj-&gt;age() &gt;= MaxTenuringThreshold) { // 年龄阈值检查</span></span>
<span class="line"><span>promote_to_old_gen(obj); // 晋升老年代</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>}</span></span></code></pre></div><h2 id="_2-如何排查定位问题" tabindex="-1">2.如何排查定位问题？ <a class="header-anchor" href="#_2-如何排查定位问题" aria-label="Permalink to &quot;2.如何排查定位问题？&quot;">​</a></h2><h3 id="_2-1-实时监控-gc健康度速诊" tabindex="-1">2.1 实时监控：GC健康度速诊 <a class="header-anchor" href="#_2-1-实时监控-gc健康度速诊" aria-label="Permalink to &quot;2.1 实时监控：GC健康度速诊&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jstat -gcutil  1000  # 每秒输出GC数据</span></span></code></pre></div><p><strong>关键指标解读</strong>：</p><ul><li><strong>OU</strong>：老年代使用率 &gt; 90% = 危险区</li><li><strong>FGCT</strong>：Full GC总耗时 &gt; 应用运行时间10% = 严重问题</li></ul><h3 id="_2-2-堆内存转储-揪出内存黑洞" tabindex="-1">2.2. 堆内存转储：揪出内存黑洞 <a class="header-anchor" href="#_2-2-堆内存转储-揪出内存黑洞" aria-label="Permalink to &quot;2.2. 堆内存转储：揪出内存黑洞&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jmap -dump:live,format=b,file=heap.bin   # 生产环境慎用live</span></span></code></pre></div><h3 id="_2-3-mat深度分析-解剖内存泄漏" tabindex="-1">2.3 MAT深度分析：解剖内存泄漏 <a class="header-anchor" href="#_2-3-mat深度分析-解剖内存泄漏" aria-label="Permalink to &quot;2.3 MAT深度分析：解剖内存泄漏&quot;">​</a></h3><p><img src="https://p3-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/ad278898a8304cea93be15fe30d8240b~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg6IuP5LiJ6K-05oqA5pyv:q75.awebp?rk3s=f64ab15b&amp;x-expires=1782401999&amp;x-signature=V2iq9Gt8A10%2Br4fRp6mAGJ8N9HA%3D" alt=""></p><h2 id="_3-优化方案" tabindex="-1">3.优化方案 <a class="header-anchor" href="#_3-优化方案" aria-label="Permalink to &quot;3.优化方案&quot;">​</a></h2><h3 id="方案1-对象池化——大对象的救赎" tabindex="-1">方案1：对象池化——大对象的救赎 <a class="header-anchor" href="#方案1-对象池化——大对象的救赎" aria-label="Permalink to &quot;方案1：对象池化——大对象的救赎&quot;">​</a></h3><p><strong>场景</strong>：高频创建10MB的文件缓存</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 反例：每次请求创建新对象</span></span>
<span class="line"><span>public void processRequest(Request req) {</span></span>
<span class="line"><span>byte[] buffer = new byte[10 * 1024 * 1024]; // 10MB</span></span>
<span class="line"><span>// ...处理逻辑</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 优化：对象池复用</span></span>
<span class="line"><span>private static final ObjectPool pool = new GenericObjectPool&lt;&gt;(</span></span>
<span class="line"><span>new BasePooledObjectFactory() {</span></span>
<span class="line"><span>@Override</span></span>
<span class="line"><span>public byte[] create() {</span></span>
<span class="line"><span>return new byte[10 * 1024 * 1024];</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>public void processRequest(Request req) throws Exception {</span></span>
<span class="line"><span>byte[] buffer = pool.borrowObject();</span></span>
<span class="line"><span>try {</span></span>
<span class="line"><span>// ...处理逻辑</span></span>
<span class="line"><span>} finally {</span></span>
<span class="line"><span>pool.returnObject(buffer);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>效果</strong>：老年代分配速率下降85%</p><h3 id="方案2-手动控制晋升" tabindex="-1">方案2：手动控制晋升 <a class="header-anchor" href="#方案2-手动控制晋升" aria-label="Permalink to &quot;方案2：手动控制晋升&quot;">​</a></h3><p><strong>问题</strong>：Survivor区过小导致对象提前晋升 <strong>优化参数</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-XX:TargetSurvivorRatio=60  # Survivor区使用阈值</span></span>
<span class="line"><span>-XX:MaxTenuringThreshold=15 # 最大晋升年龄</span></span>
<span class="line"><span>-XX:+NeverTenure            # 若Survivor足够，永不晋升（慎用！）</span></span></code></pre></div><p><strong>晋升原理</strong>：</p><p><img src="https://p3-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/d36f89971e8c43ab9ecc24609b719b43~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg6IuP5LiJ6K-05oqA5pyv:q75.awebp?rk3s=f64ab15b&amp;x-expires=1782401999&amp;x-signature=KvwCtFgGpEojgagRDuHXjnt6qpk%3D" alt=""></p><h3 id="方案3-合理分配堆空间" tabindex="-1">方案3：合理分配堆空间 <a class="header-anchor" href="#方案3-合理分配堆空间" aria-label="Permalink to &quot;方案3：合理分配堆空间&quot;">​</a></h3><p><strong>经典误区</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-Xmx4g -Xms4g  # 错误！未配置新生代</span></span></code></pre></div><p><strong>优化公式</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新生代大小 = 总堆 * 3/8</span></span>
<span class="line"><span>Eden:Survivor = 8:1:1</span></span></code></pre></div><p><strong>正确配置</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-Xmx8g -Xms8g</span></span>
<span class="line"><span>-Xmn3g  # 新生代3G (8*3/8≈3)</span></span>
<span class="line"><span>-XX:SurvivorRatio=8  # Eden:Survivor=8:1:1</span></span></code></pre></div><h3 id="方案4-卸载无用类" tabindex="-1">方案4：卸载无用类 <a class="header-anchor" href="#方案4-卸载无用类" aria-label="Permalink to &quot;方案4：卸载无用类&quot;">​</a></h3><p><strong>场景</strong>：热部署频繁的应用（如JRebel） <strong>诊断命令</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jcmd  VM.class_stats  # JDK8+</span></span>
<span class="line"><span>jcmd  GC.class_stats  # JDK11+</span></span></code></pre></div><p><strong>根治代码</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 自定义类加载器必须实现close()</span></span>
<span class="line"><span>public class HotSwapClassLoader extends URLClassLoader {</span></span>
<span class="line"><span>@Override</span></span>
<span class="line"><span>public void close() throws IOException {</span></span>
<span class="line"><span>// 1. 停止新请求</span></span>
<span class="line"><span>// 2. 卸载所有类</span></span>
<span class="line"><span>// 3. 关闭资源</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>}</span></span></code></pre></div><h3 id="方案5-颠覆传统的zgc" tabindex="-1">方案5：颠覆传统的ZGC <a class="header-anchor" href="#方案5-颠覆传统的zgc" aria-label="Permalink to &quot;方案5：颠覆传统的ZGC&quot;">​</a></h3><p><strong>传统GC痛点</strong>：</p><ul><li>CMS：内存碎片问题</li><li>G1：Mixed GC不可控</li></ul><p><strong>ZGC迁移步骤</strong>：</p><ol><li>升级JDK至17+</li><li>添加参数：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-XX:+UseZGC</span></span>
<span class="line"><span>-XX:ZAllocationSpikeTolerance=5.0  # 容忍内存分配速率波动</span></span>
<span class="line"><span>-Xmx16g -Xlog:gc*:file=gc.log</span></span></code></pre></div><p><strong>效果对比</strong>：</p><table tabindex="0"><thead><tr><th>指标</th><th>CMS</th><th>ZGC</th></tr></thead><tbody><tr><td>Full GC次数</td><td>15次/天</td><td>0次/天</td></tr><tr><td>最大暂停</td><td>2.8秒</td><td>1.2毫秒</td></tr></tbody></table><h3 id="方案6-堆外内存治理" tabindex="-1">方案6：堆外内存治理 <a class="header-anchor" href="#方案6-堆外内存治理" aria-label="Permalink to &quot;方案6：堆外内存治理&quot;">​</a></h3><p><strong>现象</strong>：堆内存正常，但Full GC频繁 <strong>根源</strong>：DirectByteBuffer的清理依赖Full GC <strong>防御方案</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 方案1：限制堆外内存</span></span>
<span class="line"><span>-XX:MaxDirectMemorySize=512m</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 方案2：主动调用Cleaner</span></span>
<span class="line"><span>ByteBuffer buffer = ByteBuffer.allocateDirect(1024);</span></span>
<span class="line"><span>Cleaner cleaner = ((DirectBuffer) buffer).cleaner();</span></span>
<span class="line"><span>if (cleaner != null) cleaner.clean();</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// 方案3：Netty的内存管理</span></span>
<span class="line"><span>PooledByteBufAllocator allocator = new PooledByteBufAllocator(true);</span></span>
<span class="line"><span>ByteBuf buffer = allocator.directBuffer(1024);</span></span>
<span class="line"><span>// ...使用后必须release!</span></span>
<span class="line"><span>buffer.release();</span></span></code></pre></div><h2 id="_4-实战案例" tabindex="-1">4.实战案例 <a class="header-anchor" href="#_4-实战案例" aria-label="Permalink to &quot;4.实战案例&quot;">​</a></h2><p><strong>背景</strong>：某支付系统日均交易10亿 <strong>症状</strong>：</p><ul><li>每分钟5次Full GC，暂停4.2秒</li><li>99线响应时间从50ms飙升至3秒</li></ul><p><strong>排查过程</strong>：</p><ol><li><code>jstat</code>显示老年代10秒内从60%→99%</li><li>MAT分析发现<code>ConcurrentHashMap$Node[]</code>占78%内存</li><li>溯源代码找到缓存黑洞：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 问题代码：永不失效的缓存</span></span>
<span class="line"><span>Map cache = new ConcurrentHashMap&lt;&gt;();</span></span>
<span class="line"><span>public void cacheTransaction(Transaction tx) {</span></span>
<span class="line"><span>cache.put(tx.getId(), tx); // Key冲突时旧对象未移除！</span></span>
<span class="line"><span>}</span></span></code></pre></div><p><strong>解决方案</strong>：</p><ol><li>改用Caffeine缓存：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Cache cache = Caffeine.newBuilder()</span></span>
<span class="line"><span>.maximumSize(10_000)</span></span>
<span class="line"><span>.expireAfterWrite(5, TimeUnit.MINUTES)</span></span>
<span class="line"><span>.build();</span></span></code></pre></div><ol><li>添加ZGC参数</li><li>重写线程池任务队列：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 用有界队列替代LinkedBlockingQueue</span></span>
<span class="line"><span>new ThreadPoolExecutor(..., new ArrayBlockingQueue&lt;&gt;(1000));</span></span></code></pre></div><p><strong>效果</strong>：</p><ul><li>Full GC降为0</li><li>99线回落至68ms</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ol><li><strong>监控三件套</strong>：</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>jstat -gcutil  1000  # 实时监控</span></span>
<span class="line"><span>-Xlog:gc*:file=gc.log     # GC日志</span></span>
<span class="line"><span>Prometheus + Grafana      # 可视化大盘</span></span></code></pre></div><ol><li><strong>参数黄金法则</strong>：</li></ol><p><img src="https://p3-xtjj-sign.byteimg.com/tos-cn-i-73owjymdk6/a823ad81c45d4f54ba575512f80b59ac~tplv-73owjymdk6-jj-mark-v1:0:0:0:0:5o6Y6YeR5oqA5pyv56S-5Yy6IEAg6IuP5LiJ6K-05oqA5pyv:q75.awebp?rk3s=f64ab15b&amp;x-expires=1782401999&amp;x-signature=4p84%2F8%2BuZzaMogiK6NknSnot0rk%3D" alt=""></p><ol><li><strong>代码军规</strong>：</li></ol><ul><li>大对象必须池化</li><li>缓存必须设置上限</li><li>线程池必须用有界队列</li></ul><ol start="2"><li><strong>GC算法选择</strong>：</li></ol><table tabindex="0"><thead><tr><th>场景</th><th>推荐算法</th></tr></thead><tbody><tr><td>堆&lt;8G</td><td>Parallel</td></tr><tr><td>8G~32G</td><td>G1</td></tr><tr><td>关键业务系统</td><td>ZGC</td></tr></tbody></table><p>Full GC不是优化出来的，是设计出来的！</p><p><strong>永远在架构设计阶段预留30%内存缓冲空间</strong>，比任何调参技巧都重要。</p><p><strong>附录：急救工具箱</strong></p><table tabindex="0"><thead><tr><th>工具</th><th>命令</th><th>适用场景</th></tr></thead><tbody><tr><td>jcmd</td><td><code>jcmd GC.run</code></td><td>主动触发Full GC</td></tr><tr><td>Arthas</td><td><code>vmtool --action getHeap</code></td><td>内存快照</td></tr><tr><td>btrace</td><td>监控DirectByteBuffer分配</td><td>堆外内存泄漏</td></tr><tr><td>PerfMa</td><td>在线分析GC日志</td><td>自动化诊断</td></tr></tbody></table>`,81)])])}const u=s(p,[["render",l]]);export{g as __pageData,u as default};
